spec.expr:
sum(
  rate(
    apisix_bandwidth{
      kubernetes_namespace=~"$namespace",
      instance=~"$instance",
      service=~"$service",
      route=~"$route",
      type="egress"
    }[$__range]
  )
) by (service, route)

sum by (route, code) (
  rate(
    apisix_http_status{
      kubernetes_namespace=~"$namespace",
      instance=~"$instance",
      service=~"$service",
      route=~"$route"
    }[$__range]
  )
)

sum(
