      kubernetes_namespace=~"$namespace",
      instance=~"$instance",
      service=~"$service",
      route=~"$route",
      type="ingress"
    }[$__range]
  )
) by (service, route)

sum(
  rate(
    apisix_bandwidth{
      kubernetes_namespace=~"$namespace",
