sum by (service, matched_uri, code) (
  increase(
    apisix_http_status{
      instance=~"$instance",
      kubernetes_namespace=~"$namespace"
    }[$__range]
  )
)

sum by (service, route, matched_uri) (
  increase(
    apisix_http_status{
      instance=~"$instance",
      service=~"$service",
      route=~"$route",
      kubernetes_namespace=~"$namespace"
    }[$__range]
  )
)

topk(
  20,
  sum by (service, route, matched_uri) (
    increase(
      apisix_http_status{
        instance=~"$instance",
        service=~"$service",
        route=~"$route",
        kubernetes_namespace=~"$namespace"
      }[$__range]
    )
  )
)

topk(
  20,
  max_over_time(
    (
      sum by (service, route, matched_uri) (
        rate(
          apisix_http_status{
            kubernetes_namespace=~"$namespace",
            instance=~"$instance",
            service=~"$service",
            route=~"$route"
          }[5m]
        )
      )
    )[$__range:5m]
  )
)

topk(
  20,
