sum by (matched_uri, service) (
  increase(
    apisix_http_status{
      kubernetes_namespace=~"$namespace",
      instance=~"$instance",
      matched_uri!="",
      service!="",
      code=~".*"
    }[$__range]
  )
)

max_over_time(
  (
    sum by (matched_uri, service) (
      rate(
        apisix_http_status{
          kubernetes_namespace=~"$namespace",
          instance=~"$instance",
          matched_uri!="",
          service!="",
          code=~".*"
        }[5m]
      )
    )
  )[$__range:5m]
)

100 *
sum by (matched_uri, service) (
  increase(
    apisix_http_status{
      kubernetes_namespace=~"$namespace",
      matched_uri=~".+",
      service=~".+",
      code=~"4..|5.."
    }[$__range]
  )
)
/
clamp_min(
  sum by (matched_uri, service) (
    increase(
      apisix_http_status{
        kubernetes_namespace=~"$namespace",
        matched_uri=~".+",
        service=~".+"
      }[$__range]
    )
  ),
  1
)

sum(
  rate(
    apisix_bandwidth{
      kubernetes_namespace=~"$namespace",
